CREATE TYPE "ai_job_status" AS ENUM ('QUEUED','PROCESSING','COMPLETED','FAILED','CANCELED');
CREATE TYPE "ai_artifact_status" AS ENUM ('SUGGESTED','ACCEPTED','REJECTED');
CREATE TYPE "ai_capability" AS ENUM ('TITLE_DESCRIPTION','SUMMARY','CHAPTERS','ACTION_ITEMS','HIGHLIGHTS','QUESTIONS_ANSWERS','TRANSLATION','FOLLOW_UP','SENSITIVE_DATA','SEARCH_INDEX');
CREATE TABLE "ai_workspace_policies" ("workspace_id" uuid PRIMARY KEY REFERENCES "workspaces"("id") ON DELETE CASCADE,"enabled" boolean DEFAULT false NOT NULL,"allowed_provider" text DEFAULT 'openai-compatible' NOT NULL,"allow_external_processing" boolean DEFAULT false NOT NULL,"monthly_token_limit" integer DEFAULT 1000000 NOT NULL,"monthly_cost_limit_microunits" bigint DEFAULT 25000000 NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"updated_by" uuid NOT NULL REFERENCES "users"("id"),CONSTRAINT "ai_workspace_policies_token_limit_check" CHECK ("monthly_token_limit">=0),CONSTRAINT "ai_workspace_policies_cost_limit_check" CHECK ("monthly_cost_limit_microunits">=0));
CREATE TABLE "ai_jobs" ("id" uuid PRIMARY KEY,"workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE CASCADE,"recording_id" uuid NOT NULL REFERENCES "recordings"("id") ON DELETE CASCADE,"transcript_id" uuid NOT NULL REFERENCES "transcripts"("id") ON DELETE CASCADE,"transcript_revision" integer NOT NULL,"input_hash" text NOT NULL,"capability" "ai_capability" NOT NULL,"status" "ai_job_status" DEFAULT 'QUEUED' NOT NULL,"prompt_template_version" text NOT NULL,"provider" text,"model" text,"question" text,"target_language" text,"requested_by" uuid NOT NULL REFERENCES "users"("id"),"input_tokens" integer,"output_tokens" integer,"cost_microunits" bigint,"currency" text,"provider_request_id_hash" text,"error_category" text,"created_at" timestamptz DEFAULT now() NOT NULL,"started_at" timestamptz,"completed_at" timestamptz,CONSTRAINT "ai_jobs_input_hash_check" CHECK(length("input_hash")=64),CONSTRAINT "ai_jobs_revision_check" CHECK("transcript_revision">=0),CONSTRAINT "ai_jobs_cost_pair_check" CHECK(("cost_microunits" IS NULL AND "currency" IS NULL) OR ("cost_microunits">=0 AND "currency"~'^[A-Z]{3}$')));
CREATE INDEX "ai_jobs_workspace_created_idx" ON "ai_jobs"("workspace_id","created_at"); CREATE INDEX "ai_jobs_recording_status_idx" ON "ai_jobs"("recording_id","status");
CREATE TABLE "ai_artifacts" ("id" uuid PRIMARY KEY,"job_id" uuid NOT NULL UNIQUE REFERENCES "ai_jobs"("id") ON DELETE CASCADE,"workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE CASCADE,"recording_id" uuid NOT NULL REFERENCES "recordings"("id") ON DELETE CASCADE,"capability" "ai_capability" NOT NULL,"content" jsonb NOT NULL,"status" "ai_artifact_status" DEFAULT 'SUGGESTED' NOT NULL,"accepted_by" uuid REFERENCES "users"("id"),"accepted_at" timestamptz,"created_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "ai_artifacts_acceptance_check" CHECK(("status"='ACCEPTED')=("accepted_by" IS NOT NULL AND "accepted_at" IS NOT NULL)));
CREATE INDEX "ai_artifacts_recording_idx" ON "ai_artifacts"("workspace_id","recording_id","created_at");
CREATE TABLE "ai_search_documents" ("id" uuid PRIMARY KEY,"workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE CASCADE,"recording_id" uuid NOT NULL REFERENCES "recordings"("id") ON DELETE CASCADE,"transcript_id" uuid NOT NULL REFERENCES "transcripts"("id") ON DELETE CASCADE,"segment_id" uuid NOT NULL UNIQUE REFERENCES "transcript_segments"("id") ON DELETE CASCADE,"start_ms" integer NOT NULL,"end_ms" integer NOT NULL,"content" text NOT NULL,"content_hash" text NOT NULL,"embedding" jsonb NOT NULL,"model" text NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "ai_search_documents_content_hash_check" CHECK(length("content_hash")=64),CONSTRAINT "ai_search_documents_timing_check" CHECK("start_ms">=0 AND "end_ms">"start_ms"));
CREATE INDEX "ai_search_documents_workspace_recording_idx" ON "ai_search_documents"("workspace_id","recording_id");
